package org.agentfrc.lesson;
import java.nio.file.*;import java.security.*;import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
public class NoteContactTest {
 static Path out;static Properties input=new Properties(),results=new Properties();static byte[] raw;
 static String sha(byte[] b)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}static double d(String k){return Double.parseDouble(input.getProperty(k));}
 @BeforeAll static void hal()throws Exception{out=Path.of(Objects.requireNonNull(System.getenv("FRC_NOTE_OUTPUT"),"Fresh native-bound input required"));raw=Files.readAllBytes(out.resolve("input.properties"));input.load(new java.io.ByteArrayInputStream(raw));assertEquals("frc-note-contact-input/v1",input.getProperty("schema"));assertEquals(input.getProperty("experimentSha256"),sha(Files.readAllBytes(out.resolve("experiment.json"))));for(String v:new String[]{"compressed","nominal"})assertEquals(input.getProperty(v+"PropertiesSha256"),sha(Files.readAllBytes(out.resolve(v+"/properties.json"))));assertTrue(d("floorMinXM")<=-.4-d("majorRadiusM")-d("minorRadiusM"),"Native floor contains entire supported torus footprint");assertTrue(d("floorMaxXM")>=.4+d("majorRadiusM")+d("minorRadiusM"),"Native floor contains entire supported torus footprint");assertEquals(-.220,d("initialXM"),1e-12);assertEquals(.0254,d("initialZM"),1e-12);assertTrue(d("rollerSpanM")/2-d("majorRadiusM")-d("minorRadiusM")>=.020,"Native full-span margin");edu.wpi.first.hal.HAL.initialize(500,0);}
 static NoteContactPlant.Config config(double mu,boolean nominal){return new NoteContactPlant.Config(d("massKg"),d("majorRadiusM"),d("minorRadiusM"),d("rollerSpanM"),d("rollerRadiusM"),d(nominal?"nominalRollerInertiaKgM2":"rollerInertiaKgM2"),d(nominal?"nominalRollerZM":"rollerZM"),d("gear"),mu);}
 @AfterAll static void write()throws Exception{results.setProperty("inputSha256",sha(raw));for(Class<?> c:new Class<?>[]{NoteContactPlant.class,NoteAdvanceController.class,NoteContactRig.class})results.setProperty(c.getSimpleName()+"ClassSha256",sha(c.getResourceAsStream(c.getSimpleName()+".class").readAllBytes()));results.setProperty("capture","unestablished");results.setProperty("engineeringAcceptance","blocked");try(var w=Files.newBufferedWriter(out.resolve("result.properties"))){results.store(w,"Development evidence only");}}
 static double[] values(NoteContactPlant.Sample a){return new double[]{a.x(),a.z(),a.vx(),a.vz(),a.rollerOmega(),a.angle(),a.bus(),a.batteryAmps(),a.mechanicalResidual(),a.normalLoss(),a.frictionLoss(),a.maxEvaluatedRollerNormal()};}
 record Run(List<double[]> rows,String outcome){}
 static Run run(double mu,boolean nominal,int steps)throws Exception{String id=(nominal?"nominal":"compressed")+"-mu"+mu+"-steps"+steps;var rows=new ArrayList<double[]>();StringBuilder csv=new StringBuilder("t,x,z,vx,vz,omega,angle,bus,current,residual,normalLoss,frictionLoss,maxEvaluatedRollerNormal,normalForce,constraintMoment,closestRimY,closestRimLoci,beamBlocked,pulses,phase\n");String outcome="unobserved",finalPhase="not-run",unsupportedTick="none";int pulses=0;double maxNormal=0;try(var rig=new NoteContactRig(config(mu,nominal),1)){for(int i=0;i<220;i++){try{var a=rig.step(true,steps);rows.add(values(a));finalPhase=rig.controller.phase().toString();pulses=rig.controller.pulses();maxNormal=Math.max(maxNormal,a.maxEvaluatedRollerNormal());csv.append((i+1)*.02);for(double v:values(a))csv.append(',').append(v);csv.append(',').append(a.rollerNormal()).append(',').append(a.constraintMoment()).append(',').append(NoteContactPlant.patchY(config(mu,nominal),a.x())).append(',').append(NoteContactPlant.patchY(config(mu,nominal),a.x())==0?1:2).append(',').append(NoteContactPlant.beamBlocked(config(mu,nominal),a.x(),0)).append(',').append(rig.controller.pulses()).append(',').append(rig.controller.phase()).append('\n');assertTrue(Math.abs(a.mechanicalResidual())<2e-5,"Mechanical ledger residual");assertTrue(a.normalLoss()>=0&&a.frictionLoss()>=0);outcome=rig.controller.phase()==NoteAdvanceController.Phase.STOP?"two-pulse-stop-not-capture":rig.controller.phase()==NoteAdvanceController.Phase.FAULT?"controller-fault":"no-beam-stop";}catch(IllegalArgumentException e){maxNormal=Math.max(maxNormal,rig.maxEvaluatedRollerNormal());boolean electrical=e.getMessage().contains("Unsupported regeneration"),geometry=e.getMessage().contains("Finite fixture face domain")||e.getMessage().contains("Contact state domain");assertTrue(electrical||geometry,e.getMessage());outcome=(electrical?"unsupported-electrical: ":"unsupported-geometry: ")+e.getMessage();unsupportedTick="["+(i*.02)+","+((i+1)*.02)+"] seconds; failure within tick";finalPhase=rig.controller.phase().toString();pulses=rig.controller.pulses();break;}}}if(nominal||mu>0)assertEquals(0,maxNormal,"No evaluated roller contact in stalled/coasting controls");else assertTrue(maxNormal>0,"Compressed zero-friction case really contacts roller");Files.writeString(out.resolve(id+".csv"),csv,StandardOpenOption.CREATE_NEW);results.setProperty(id+".outcome",outcome);results.setProperty(id+".controllerPhase",finalPhase);results.setProperty(id+".completedPulses",Integer.toString(pulses));results.setProperty(id+".maxEvaluatedRollerNormalN",Double.toString(maxNormal));results.setProperty(id+".unsupportedTick",unsupportedTick);return new Run(rows,outcome);}
 @Test void nativeBoundProfilesAndAlignedRefinement()throws Exception{double[] max=new double[12];for(boolean nominal:new boolean[]{false,true})for(double mu:new double[]{0,.2,.4,.8}){var a=run(mu,nominal,200);var b=run(mu,nominal,400);assertEquals(a.outcome().split(":")[0],b.outcome().split(":")[0],"Refined outcome category");assertEquals(a.rows.size(),b.rows.size(),"Same supported sampled horizon");for(int i=0;i<a.rows.size();i++)for(int j=0;j<12;j++)max[j]=Math.max(max[j],Math.abs(a.rows.get(i)[j]-b.rows.get(i)[j]));}double[] tol={1e-5,1e-5,1e-4,1e-4,1e-3,1e-4,1e-4,.005,2e-5,2e-5,2e-5,.001};for(int j=0;j<12;j++){results.setProperty("refinementMax."+j,Double.toString(max[j]));assertTrue(max[j]<tol[j],"Refinement component "+j+" delta="+max[j]);}}
 @Test void independentFiniteEntryVector(){var p=NoteContactPlant.upper(config(.2,false),-.168,.0254,.15,0,-10);assertEquals(2.180717508096293,p.normal(),1e-10);assertEquals(1.2585792559188793,p.fx(),1e-10);assertEquals(-2.4929993122268845,p.fz(),1e-10);assertEquals(.08862435952903334,p.rollerTorque(),1e-10);assertEquals(-.42424527494789394,p.constraintMoment(),1e-10);assertEquals(-.6974567069025016,p.fx()*.15+p.rollerTorque()*-10,1e-10);}
 @Test void holeCoexistsWithTwoRimContacts(){var c=config(.2,false);assertEquals(.1524,NoteContactPlant.patchY(c,0),1e-12);assertFalse(NoteContactPlant.beamBlocked(c,0,0));assertTrue(NoteContactPlant.upper(c,0,.0254,0,0,0).normal()>0);assertTrue(NoteContactPlant.beamBlocked(c,-.15,0));assertFalse(NoteContactPlant.beamBlocked(c,-.22,0));assertTrue(NoteContactPlant.beamBlocked(c,c.majorRadius()-c.minorRadius(),0));assertTrue(NoteContactPlant.beamBlocked(c,c.majorRadius()+c.minorRadius(),0));assertFalse(NoteContactPlant.beamBlocked(c,Math.nextDown(c.majorRadius()-c.minorRadius()),0));assertFalse(NoteContactPlant.beamBlocked(c,Math.nextUp(c.majorRadius()+c.minorRadius()),0));assertEquals(0,NoteContactPlant.upper(config(.2,true),0,.0254,0,0,0).normal(),1e-10);}
 @Test void endpointAggregateForceAndEnergyAreContinuous(){var c=config(.2,false);double eps=1e-9;var inside=NoteContactPlant.upper(c,-c.majorRadius()+eps,.0254,.1,0,-10);var outside=NoteContactPlant.upper(c,-c.majorRadius()-eps,.0254,.1,0,-10);assertEquals(inside.normal(),outside.normal(),1e-5);assertEquals(inside.potential(),outside.potential(),1e-10);assertEquals(inside.fx(),outside.fx(),1e-5);assertTrue(NoteContactPlant.patchY(c,-c.majorRadius()+eps)>0);assertEquals(0,NoteContactPlant.patchY(c,-c.majorRadius()-eps));var center=NoteContactPlant.upper(c,0,.0254,.1,0,-10);var patches=NoteContactPlant.patches(c,0,.0254,.1,0,-10);assertEquals(2,patches.length);double fx=0,fz=0,mx=0,mz=0;for(var p:patches){fx+=p.fx();fz+=p.fz();mx+=p.y()*p.fz();mz-=p.y()*p.fx();}assertEquals(center.fx(),fx);assertEquals(center.fz(),fz);assertEquals(0,mx);assertEquals(0,mz);assertEquals(1,NoteContactPlant.patches(c,-c.majorRadius(),.0254,.1,0,-10).length);}
 @Test void unsupportedBoreAndInvalidStates(){var rejected=new NoteContactPlant(config(.2,false),-.168,.0254,.15);assertEquals(0,rejected.maxEvaluatedRollerNormal());var failure=assertThrows(IllegalArgumentException.class,()->rejected.step(-1e-5,.0001));assertTrue(failure.getMessage().startsWith("Unsupported regeneration"));assertTrue(rejected.maxEvaluatedRollerNormal()>0,"Rejected RK stages retain evaluated contact without a successful step");var c=config(.2,false);assertThrows(IllegalArgumentException.class,()->new NoteContactPlant.Config(c.mass(),c.majorRadius(),c.minorRadius(),.3,c.rollerRadius(),c.rollerInertia(),c.rollerZ(),c.gear(),c.floorMu()));assertThrows(IllegalArgumentException.class,()->NoteContactPlant.upper(config(.2,false),0,.09,0,0,0));assertThrows(IllegalArgumentException.class,()->NoteContactPlant.upper(config(.2,false),Double.NaN,.0254,0,0,0));assertThrows(IllegalArgumentException.class,()->new NoteContactPlant(config(.2,false),0,.015,0));}
 @Test void disabledFaultLatches(){try(var rig=new NoteContactRig(config(.2,false),1)){rig.step(false,200);assertEquals(NoteAdvanceController.Phase.FAULT,rig.controller.phase());rig.step(true,200);assertEquals(NoteAdvanceController.Phase.FAULT,rig.controller.phase());}}
 @Test void wrongEncoderSignFaults(){try(var rig=new NoteContactRig(config(.2,false),-1)){for(int i=0;i<5;i++)rig.step(true,200);assertEquals(NoteAdvanceController.Phase.FAULT,rig.controller.phase());}}
 @Test void blockedBeamFaultsAtInitialization(){try(var rig=new NoteContactRig(config(.2,false),1,1)){rig.step(true,200);assertEquals(NoteAdvanceController.Phase.FAULT,rig.controller.phase());}}
 @Test void missingBeamNeverCompletes(){try(var controller=new NoteAdvanceController()){var encoder=edu.wpi.first.wpilibj.simulation.EncoderSim.createForChannel(0);var beam=new edu.wpi.first.wpilibj.simulation.DIOSim(2);var pwm=new edu.wpi.first.wpilibj.simulation.PWMSim(0);edu.wpi.first.wpilibj.simulation.RoboRioSim.setVInVoltage(12);beam.setValue(true);for(int i=0;i<201;i++){encoder.setCount(-i);controller.periodic(true);}assertEquals(NoteAdvanceController.Phase.FAULT,controller.phase());assertEquals(0,pwm.getSpeed());beam.setValue(false);controller.periodic(true);assertEquals(NoteAdvanceController.Phase.FAULT,controller.phase());assertEquals(0,pwm.getSpeed());}try(var rig=new NoteContactRig(config(.2,false),1,2)){try{for(int i=0;i<220;i++)rig.step(true,200);}catch(IllegalArgumentException e){assertTrue(e.getMessage().contains("Unsupported regeneration")||e.getMessage().contains("Finite fixture face domain")||e.getMessage().contains("Contact state domain"));}assertNotEquals(NoteAdvanceController.Phase.STOP,rig.controller.phase());}}
 @Test void twoPulsesRequiredAndDisableOverrides(){try(var c=new NoteAdvanceController()){var beam=new edu.wpi.first.wpilibj.simulation.DIOSim(2);var encoder=edu.wpi.first.wpilibj.simulation.EncoderSim.createForChannel(0);var pwm=new edu.wpi.first.wpilibj.simulation.PWMSim(0);edu.wpi.first.wpilibj.simulation.RoboRioSim.setVInVoltage(12);encoder.setCount(0);beam.setValue(true);c.periodic(true);assertEquals(-.12,pwm.getSpeed(),.002);beam.setValue(false);c.periodic(true);beam.setValue(true);c.periodic(true);assertEquals(NoteAdvanceController.Phase.FEED,c.phase());assertEquals(1,c.pulses());beam.setValue(false);c.periodic(true);beam.setValue(true);c.periodic(true);assertEquals(NoteAdvanceController.Phase.STOP,c.phase());assertEquals(0,pwm.getSpeed());c.periodic(false);assertEquals(NoteAdvanceController.Phase.FAULT,c.phase());}}}














